// Stolen from https://alexwlchan.net/2025/localising-the-time/
// and https://alexwlchan.net/2020/human-friendly-dates-in-javascript/

if(!window.localtime_bound) {
  window.localtime_bound = true;

  const date_formatter = new Intl.DateTimeFormat(
    ["nl-NL"], {"year": "numeric", "month": "long", "day": "numeric"}
  )

  const time_formatter = new Intl.DateTimeFormat(
    ["nl-NL"], {"hour": "numeric", "minute": "numeric"}
  )

  const timestamp_of = (time) => time.getAttribute("datetime") || time.innerText;
  const same_day = (one, another) => date_formatter.format(new Date(one)) == date_formatter.format(new Date(another));

  function format_local_time(time) {
    const timestamp = timestamp_of(time);
    const previous = time.previousElementSibling;

    if(time.getAttribute("local") == "time-if-same-day"
      && previous?.matches("time[local]")
      && same_day(timestamp, timestamp_of(previous))) {
      return time_formatter.format(new Date(timestamp));
    }

    return get_human_friendly_date(timestamp);
  }

  function localize_times(root) {
    const nodes = root.matches("time[local]")
      ? [root] : root.querySelectorAll("time[local]");

    nodes.forEach((time) => {
      if(time.hasAttribute("title")) return; // already localised
      time.setAttribute("title", time.innerText);
      time.innerText = format_local_time(time);
    });
  }

  function get_human_friendly_date(str) {
    const date = new Date(str);

    const today = new Date();
    const yesterday = new Date().setDate(today.getDate() - 1);

    // We have to compare the *formatted* dates rather than the actual dates.
    // (For example, if the UTC date and the localised date fall on either side
    // of midnight.)
    if(same_day(date, today)) {
      return "today " + time_formatter.format(date);
    }
    else if(same_day(date, yesterday)) {
      return "yesterday " + time_formatter.format(date);
    }
    else {
      return date_formatter.format(date) + " " + time_formatter.format(date);
    }
  }

  function get_human_friendly_delta(str) {
    const date = new Date(Date.parse(str));
    const now = new Date();

    const delta_milliseconds = now - date;
    const delta_seconds = Math.floor(delta_milliseconds / 1000);
    const delta_minutes = Math.floor(delta_seconds / 60);
    const delta_hours = Math.floor(delta_minutes / 60);

    if(delta_seconds < 5) return "just now";
    else if(delta_seconds < 60) return delta_seconds + " seconds ago";
    else if(delta_minutes == 1) return "1 minute ago";
    else if(delta_minutes < 60) return delta_minutes + " minutes ago";
    else if(delta_hours == 1) return "1 hour ago";
    else if(delta_hours < 6) return delta_hours + " hours ago";
    else return "";
  }

  const init = function() {
    localize_times(document.body);

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if(node.nodeType == 1) localize_times(node);
        });
      });
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
    });
  };

  if(document.readyState == "loading") window.addEventListener("DOMContentLoaded", init);
  else init();
}
